/**
 * ContactPage Component
 * Purpose: Displays contact information and contact form for user inquiries
 * Shows corporate address, phone numbers, email, WhatsApp, and social media links
 * Integrates with live chat widget to auto-fill contact form
 */
import React, { useState, useEffect } from 'react';
import ContactForm from '../components/ContactForm';
import './ContactPage.css';

const ContactPage = () => {
  const [formData, setFormData] = useState(null);

  useEffect(() => {
    const existingLink = document.querySelector('link[data-font-awesome="true"]');
    if (!existingLink) {
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css';
      link.integrity = 'sha512-DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==';
      link.crossOrigin = 'anonymous';
      link.referrerPolicy = 'no-referrer';
      link.setAttribute('data-font-awesome', 'true');
      document.head.appendChild(link);
    }
  }, []);

  useEffect(() => {
    const storedFormData = sessionStorage.getItem('chatSupportFormData');
    if (storedFormData) {
      try {
        const parsed = JSON.parse(storedFormData);
        setFormData(parsed);
      } catch (error) {
        console.warn('Unable to parse stored chat form data', error);
      } finally {
        sessionStorage.removeItem('chatSupportFormData');
      }
    }
  }, []);

  const contactInfo = {
    corporate: {
      name: 'HeavenMatch Matrimony Services Pvt. Ltd.',
      address: [
        'Plot No. 123, Sector 18,',
        'Gurugram, Haryana - 122015',
        'India'
      ]
    },
    phones: [
      { label: 'India Support (Toll-Free)', number: '1800-123-4567', link: 'tel:1800-123-4567' },
      { label: 'Mumbai Secondary Phone', number: '+91-22-9876-5432', link: 'tel:+91-22-9876-5432' },
      { label: 'Safety Hotline (24/7)', number: '1800-999-8888', link: 'tel:1800-999-8888', urgent: true }
    ],
    email: 'support@heavenmatch.com',
    whatsapp: 'https://wa.me/919876543210'
  };

  return (
    <div className="contact-page-wrapper">
      <div className="contact-page-header">
        <div className="container">
          <h1>Contact Us</h1>
          <p>We're here to help! Reach out to us through any of the channels below.</p>
        </div>
      </div>

      <div className="container">
        <div className="contact-page-layout">
          {/* Left Sidebar - Contact Information */}
          <aside className="contact-sidebar">
            {/* Corporate Address */}
            <div className="info-card">
              <div className="card-header">
                <i className="fas fa-building"></i>
                <h2>Corporate Address</h2>
              </div>
              <div className="card-content address-content">
                <p className="company-name">{contactInfo.corporate.name}</p>
                {contactInfo.corporate.address.map((line, index) => (
                  <p key={index}>{line}</p>
                ))}
              </div>
            </div>

            {/* Phone Numbers */}
            <div className="info-card">
              <div className="card-header">
                <i className="fas fa-phone"></i>
                <h2>Phone Support</h2>
              </div>
              <div className="card-content phone-content">
                {contactInfo.phones.map((phone, index) => (
                  <div key={index} className={`phone-item ${phone.urgent ? 'urgent' : ''}`}>
                    <p className="phone-label">{phone.label}</p>
                    <a href={phone.link} className="phone-link">
                      {phone.number}
                    </a>
                  </div>
                ))}
              </div>
            </div>

            {/* Email */}
            <div className="info-card">
              <div className="card-header">
                <i className="fas fa-envelope"></i>
                <h2>Email Support</h2>
              </div>
              <div className="card-content email-content">
                <a href={`mailto:${contactInfo.email}`} className="email-link">
                  {contactInfo.email}
                </a>
                <p className="email-note">We respond within 24 hours</p>
              </div>
            </div>

            {/* WhatsApp */}
            <div className="info-card">
              <div className="card-header">
                <i className="fab fa-whatsapp"></i>
                <h2>WhatsApp Support</h2>
              </div>
              <div className="card-content whatsapp-content">
                <p>Get instant support via WhatsApp</p>
                <a href={contactInfo.whatsapp} className="whatsapp-btn" target="_blank" rel="noopener noreferrer">
                  <i className="fab fa-whatsapp"></i> Chat on WhatsApp
                </a>
              </div>
            </div>
          </aside>

          {/* Main Content - Contact Form */}
          <main className="contact-main-content">
            <div className="form-container">
              <div className="form-header">
                <h2>Send Us a Message</h2>
                <p>Fill out the form below and we'll get back to you as soon as possible.</p>
              </div>
              <ContactForm initialData={formData} />
            </div>
          </main>
        </div>
      </div>
    </div>
  );
};

export default ContactPage;

